import{_ as o,o as l,c as i,aw as t}from"./chunks/framework.DLufY-ao.js";const f=JSON.parse('{"title":"Gitflow","description":"","frontmatter":{},"headers":[],"relativePath":"common/git/theory/gitflow.md","filePath":"wiki/dev-commit/common/git/theory/gitflow.md"}'),a={name:"common/git/theory/gitflow.md"};function d(c,e,r,s,n,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="gitflow" tabindex="-1">Gitflow <a class="header-anchor" href="#gitflow" aria-label="Permalink to &quot;Gitflow&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Gitflow</strong> - модель управления ветками. Есть две основные ветки: <code>master</code> и <code>develop</code></li><li><strong>gitflow-avh</strong> - инструмент для работы с Gitflow</li></ul></div><h2 id="ветки" tabindex="-1">Ветки <a class="header-anchor" href="#ветки" aria-label="Permalink to &quot;Ветки&quot;">​</a></h2><ul><li><code>master</code> - содержится тот же код, что и в рабочей (продакт) версии проекта</li><li><code>release</code> - подготовка к новому релизу проекта</li><li><code>beta</code> - бета-версия проекта</li><li><code>develop</code> - происходит вся работа</li></ul><h3 id="ветки-задач" tabindex="-1">Ветки задач <a class="header-anchor" href="#ветки-задач" aria-label="Permalink to &quot;Ветки задач&quot;">​</a></h3><ul><li><code>feature</code> - создаются в процессе работы над develop, их может быть неограниченное количество</li><li><code>improvement</code> - улучшение</li><li><code>bug</code> - исправление багов</li><li><code>bugfix</code> - исправление багов</li><li><code>hotfix</code> - срочное исправление багов, найденных, например, на продакте</li><li><code>fix</code> - небольшие исправления</li></ul><h2 id="рабочии-процесс-в-gitflow" tabindex="-1">Рабочий процесс в Gitflow <a class="header-anchor" href="#рабочии-процесс-в-gitflow" aria-label="Permalink to &quot;Рабочий процесс в Gitflow&quot;">​</a></h2><ol><li>Создается репозиторий</li><li>Репозиторий инициализируется</li><li>Начинается работа на ветке <code>develop</code></li><li>Возникает необходимость опробовать новую штуку - создается <code>feature-ветка</code> и делаются коммиты</li><li>Закончив работу на <code>feature-ветке</code>, вы сливаете ее с <code>develop</code></li><li>Если вы довольны текущей версией, но хотите продолжить работу, создается ветка <code>release</code>, куда перемещается текущая версия. Правка багов будет происходить на этой же ветке</li><li>Когда с веткой <code>release</code> покончено, время слить ее в master (и обратно в <code>develop</code>) и продолжить работу с <code>develop</code></li><li>Кроме того, этот момент можно отметить на <code>master-ветке</code></li></ol><h2 id="code-review-в-github" tabindex="-1">Code review в GitHub <a class="header-anchor" href="#code-review-в-github" aria-label="Permalink to &quot;Code review в GitHub&quot;">​</a></h2><ol><li>Создать репозиторий</li><li>Основная ветка разработки &quot;dev&quot;</li><li>Под каждую задачу создается ветка от &quot;dev&quot;</li><li>Создание PR (Pull Request) для слияния ветки задачи с веткой &quot;dev&quot;</li><li>Ссылка на PR руководителю</li><li>Если всё ок, слияние веток, если нет, то исправление замечаний</li><li>Если несколько задач и несколько веток, то вливать нужно не ветки полностью, а только отдельные коммиты</li></ol>',11)])])}const m=o(a,[["render",d]]);export{f as __pageData,m as default};
